from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
from itertools import combinations
from collections import defaultdict, deque

n = 23
edge_var = {}
cnt = 0
for u in range(n):
    for v in range(u+1,n):
        cnt += 1
        edge_var[(u,v)] = cnt

def ev(u,v):
    if u>v: u,v=v,u
    return edge_var[(u,v)]

next_var = [cnt]
def nv():
    next_var[0] += 1
    return next_var[0]

clauses = []

for u,v in combinations(range(n),2):
    lits = [ev(u,v)]
    for w in range(n):
        if w==u or w==v: continue
        x = nv()
        clauses.append([-ev(u,w), -ev(w,v), x])
        lits.append(x)
    for a in range(n):
        if a==u or a==v: continue
        for b in range(n):
            if b==u or b==v or b==a: continue
            y = nv()
            clauses.append([-ev(u,a), -ev(a,b), -ev(b,v), y])
            lits.append(y)
    top = next_var[0]
    cnf = CardEnc.atmost(lits=lits, bound=1, top_id=top, encoding=EncType.seqcounter)
    for c in cnf.clauses:
        clauses.append(c)
        for l in c:
            if abs(l)>next_var[0]:
                next_var[0]=abs(l)

for v in range(n):
    lits = [ev(v,u) for u in range(n) if u!=v]
    top = next_var[0]
    cnf = CardEnc.atleast(lits=lits, bound=3, top_id=top, encoding=EncType.seqcounter)
    for c in cnf.clauses:
        clauses.append(c)
        for l in c:
            if abs(l)>next_var[0]: next_var[0]=abs(l)
    top = next_var[0]
    cnf = CardEnc.atmost(lits=lits, bound=4, top_id=top, encoding=EncType.seqcounter)
    for c in cnf.clauses:
        clauses.append(c)
        for l in c:
            if abs(l)>next_var[0]: next_var[0]=abs(l)

print("clauses:", len(clauses), "vars:", next_var[0])

solver = Glucose3()
for c in clauses:
    solver.add_clause(c)

print("solving...")
res = solver.solve()
print(res)
if res:
    model = solver.get_model()
    mset = set(model)
    edges=[]
    for (u,v),var in edge_var.items():
        if var in mset:
            edges.append((u,v))
    print(len(edges))
    adj = defaultdict(set)
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    degs = [len(adj[v]) for v in range(n)]
    print("degrees:", degs)
    def girth():
        g=float('inf')
        for s in range(n):
            dist={s:0}; parent={s:-1}
            q=deque([s])
            while q:
                u=q.popleft()
                for w in adj[u]:
                    if w not in dist:
                        dist[w]=dist[u]+1; parent[w]=u
                        q.append(w)
                    elif parent[u]!=w and dist[w]>=dist[u]:
                        g=min(g,dist[u]+dist[w]+1)
        return g
    print("girth:",girth())
    print(edges)

