n = 23
E = {}
for u in range(n):
    for v in range(u+1,n):
        E[(u,v)] = Bool(f"e_{u}_{v}")

def eE(u,v):
    if u>v: u,v=v,u
    return E[(u,v)]

s = Solver()

for v in range(n):
    lits = [eE(v,u) for u in range(n) if u!=v]
    s.add(PbGe([(l,1) for l in lits], 3))
    s.add(PbLe([(l,1) for l in lits], 4))

for u,v in combinations(range(n),2):
    terms = [(eE(u,v),1)]
    for w in range(n):
        if w==u or w==v: continue
        x = Bool(f"p2_{u}_{v}_{w}")
        s.add(Or(Not(eE(u,w)), Not(eE(w,v)), x))
        terms.append((x,1))
    for a in range(n):
        if a==u or a==v: continue
        for b in range(n):
            if b==u or b==v or b==a: continue
            y = Bool(f"p3_{u}_{v}_{a}_{b}")
            s.add(Or(Not(eE(u,a)), Not(eE(a,b)), Not(eE(b,v)), y))
            terms.append((y,1))
    s.add(PbLe(terms, 1))

print("checking...")
